(function(E){ const x = E["sales-m2"] = E["sales-m2"] || {units:{}}; x.units["sales-2-3"] = {"grammar":{"id":"c-sales-2-3-g","level":"B1","course":"sales","unit":"sales-2-3","title":"Terms with if and unless","titleTr":"if ve unless ile koşullar","titleFa":"شرط‌ها با if و unless","formsTable":{"headers":{"en":["Pattern","Example from a quote"],"tr":["Kalıp","Tekliften örnek"],"fa":["الگو","مثال از یک پیشنهاد قیمت"]},"rows":[["If + present, will / can + verb","If you order 200, the price will be EUR 40.00."],["unless + positive verb","We can't start unless the deposit arrives."],["valid + time","This quote is valid for 30 days."],["Incoterm + place","FCA Izmir"]]},"wrong":"If you will order 200 cartons, the price will be EUR 40.00.","right":"If you order 200 cartons, the price will be EUR 40.00.","blank":{"sentence":"If you ___ by Friday, we can ship in early May.","word":"confirm","distractors":["will confirm","confirmed"]},"wrong2":"We can't start production unless you don't pay the deposit.","right2":"We can't start production unless you pay the deposit.","blank2":{"sentence":"We cannot ship the goods ___ we receive the import licence.","word":"unless","distractors":["if","because"],"hint2":{"en":"The goods can't move until the licence comes: the gap means 'if not'. Which word means that?","tr":"Lisans gelmeden mal yola çıkamaz: boşluk 'if not' anlamında. Hangi kelime bu anlama gelir?","fa":"تا مجوز نرسد کالا حرکت نمی‌کند: جای خالی یعنی ⁨if not⁩. کدام کلمه این معنی را دارد؟"},"why":{"en":"unless: it means 'if not', so the verb after it stays positive: no licence, no shipping. 'if' gives the opposite meaning, and 'because' gives a reason, not a condition.","tr":"unless: 'if not' anlamına gelir, bu yüzden arkasındaki fiil olumlu kalır: lisans yoksa sevkiyat da yok. 'if' tam tersi anlamı verir; 'because' ise koşul değil, neden bildirir.","fa":"⁨unless⁩: یعنی ⁨if not⁩، برای همین فعل بعدش مثبت می‌ماند: مجوز نباشد، ارسالی هم در کار نیست. ⁨if⁩ معنی را برعکس می‌کند و ⁨because⁩ دلیل می‌گوید، نه شرط."}},"expParts":{"tryFrom":"blank","rule":[{"en":"State a condition with if + present, then will or can + verb.","tr":"Bir koşulu if + geniş zaman, sonra will ya da can + fiil ile söyle.","fa":"برای گفتن یک شرط، در بخش if زمان حال بیاور و در بخش دوم will یا can با فعل ساده.","ex":"If you order 200, the price will be EUR 40.00."},{"en":"Use the present after if, not will, even for the future.","tr":"if'ten sonra, gelecek için bile, will değil geniş zaman kullan.","fa":"بعد از if حتی برای آینده زمان حال می‌آید، نه will.","ex":"If you confirm by Friday, not If you will confirm"},{"en":"unless = if not, so the verb after it is positive.","tr":"unless = eğer ... değilse; ardından gelen fiil olumludur.","fa":"کلمه‌ی unless همان «مگر اینکه» است، پس فعل بعدش مثبت است.","ex":"We can't start unless the deposit arrives."}],"test":{"en":"Look right after if: is there will? Take it out. Look right after unless: is there not? Take it out.","tr":"if'ten hemen sonrasına bak: will var mı? Çıkar. unless'tan hemen sonrasına bak: not var mı? Çıkar.","fa":"درست بعد از if را نگاه کن: will هست؟ آن را بردار. درست بعد از unless را نگاه کن: not هست؟ آن را بردار."},"contrast":{"en":"Learners write 'if you will order' and 'unless you don't pay', because their own language allows future or a negative there. English uses present after if and a positive verb after unless.","tr":"Türkçede koşulda gelecek zaman olabilir ('sipariş verecekseniz') ve 'unless' anlamı olumsuz bir ekle kurulur ('ödemedikçe'). Bu yüzden 'if you will order' ve 'unless you don't pay' yazılıyor. İngilizcede if'ten sonra geniş zaman, unless'tan sonra olumlu fiil gelir.","fa":"در فارسی بعد از «اگر» فعل التزامی می‌آید («اگر سفارش بدهید»)، ولی گاهی از ترجمه‌ی «خواهید داد» will را هم می‌آوریم. «مگر اینکه» هم با فعل مثبت می‌آید، درست مثل unless: «مگر اینکه پیش‌پرداخت برسد»."}},"errorWatch":[{"find":["if you will order","if you will pay","if you will confirm","if you will send","if they will order","if we will","if the deposit will"],"fix":{"en":"No will after if: 'If you order 200 cartons, the price will be...'.","tr":"If'ten sonra will gelmez: 'If you order 200 cartons, the price will be...'.","fa":"بعد از if، will نمی‌آید: «If you order 200 cartons, the price will be...»."}},{"find":["unless you don't","unless we don't","unless they don't","unless you do not","unless the deposit doesn't"],"fix":{"en":"unless already means 'if not': 'unless you pay the deposit'.","tr":"unless zaten 'if not' demektir: 'unless you pay the deposit'.","fa":"unless خودش یعنی «if not»: «unless you pay the deposit»."}}]},"b2":{"id":"c-sales-2-3-b2","level":"B2","track":"B2","course":"sales","unit":"sales-2-3","title":"Firm conditions: provided that, as long as","titleTr":"Net koşullar: provided that, as long as","titleFa":"شرط‌های قاطع: provided that و as long as","formsTable":{"headers":{"en":["Word","Feel","Example"],"tr":["Kelime","Hissi","Örnek"],"fa":["کلمه","حس","مثال"]},"rows":[["as long as","spoken, friendly","as long as the order is 200 or more"],["provided (that)","written, firm","provided that the deposit arrives this month"],["on condition that","very formal, contracts","on condition that the price is not published"]]},"wrong":"We can deliver in May provided that you will pay the deposit this week.","right":"We can deliver in May provided that you pay the deposit this week.","blank":{"sentence":"We can offer EUR 40.00 ___ the total order is at least 200 cartons.","word":"as long as","distractors":["as well as","as much as"]},"wrong2":"Provided you will confirm by Friday, the price is fixed.","right2":"Provided you confirm by Friday, the price is fixed.","blank2":{"sentence":"Delivery is in six weeks, ___ that we receive the deposit on time.","word":"provided","distractors":["unless","even"]},"expParts":{"tryFrom":"blank2","rule":[{"en":"provided (that) / as long as / on condition that = only if.","tr":"provided (that) / as long as / on condition that = yalnızca ... ise.","fa":"عبارت‌های provided (that)، as long as و on condition that یعنی «فقط به شرطی که».","ex":"as long as the order is 200 or more"},{"en":"Present after them, never will.","tr":"Ardından geniş zaman, asla will değil.","fa":"بعد از این عبارت‌ها زمان حال می‌آید، هرگز will.","ex":"Provided you confirm by Friday, ..."},{"en":"Speech: as long as. Emails and contracts: provided that.","tr":"Konuşma: as long as. E-posta ve sözleşme: provided that.","fa":"در گفتار as long as بهتر است و در ایمیل و قرارداد provided that.","ex":"..., provided that the deposit arrives this month."}],"test":{"en":"Swap the word for 'only if'. If the sentence still works, the word is right; then check there is no will after it.","tr":"Kelimeyi 'only if' ile değiştir. Cümle hâlâ anlamlıysa kelime doğrudur; sonra ardından will olmadığını kontrol et.","fa":"کلمه را با only if عوض کن. اگر جمله هنوز درست است، کلمه درست است؛ بعد مطمئن شو پس از آن will نیامده باشد."},"contrast":{"en":"Turkish says 'şartıyla' at the end of the condition ('ön ödeme gelmesi şartıyla'), and Persian «به شرطی که» at the start. English puts provided that or as long as at the start, like Persian, with a present verb.","tr":"Türkçede koşulun sonuna 'şartıyla' ya da '-mek kaydıyla' gelir: 'ön ödemenin zamanında gelmesi şartıyla'. İngilizcede provided that ya da as long as koşulun başına gelir ve ardından geniş zaman kullanılır.","fa":"در فارسی «به شرطی که» اول شرط می‌آید، درست مثل provided that و as long as در انگلیسی. فقط یادت باشد بعدش زمان حال بیاوری، نه will."}},"errorWatch":[{"find":["provided that you will","provided you will","as long as you will","on condition that you will","as long as the order will"],"fix":{"en":"Use the present after provided that or as long as: 'provided that you pay'.","tr":"Provided that ya da as long as'ten sonra geniş zaman kullan: 'provided that you pay'.","fa":"بعد از provided that یا as long as زمان حال بیاور: «provided that you pay»."}}],"useIn":{"en":"B2: write one term in your quote with provided that or as long as.","tr":"B2: teklifindeki bir koşulu provided that ya da as long as ile yaz.","fa":"مسیر B2: یکی از شرط‌های پیشنهادت را با provided that یا as long as بنویس."},"exitItem":{"from":"sales-2-3","kind":"blank","prompt":"We'll hold this price for you ___ you confirm the order this month.","options":["as long as","as soon","as well"],"correct":0,"why":{"en":"as long as: it sets a firm condition, like 'only if'. 'As soon' and 'as well' don't make a condition.","tr":"as long as: 'only if' gibi kesin bir koşul koyar. 'As soon' ve 'as well' koşul kurmaz.","fa":"as long as درست است، چون مثل only if یک شرط قطعی می‌گذارد. as soon و as well شرط نمی‌سازند."},"hint2":{"en":"You need a condition here that means 'only if'. Which choice is a complete condition word?","tr":"Burada 'only if' anlamında bir koşul gerekiyor. Hangi seçenek tam bir koşul ifadesi?","fa":"این‌جا شرطی لازم است که معنی ⁨only if⁩ بدهد. کدام گزینه یک عبارت شرطی کامل است؟"}}},"vocab":{"id":"c-sales-2-3-v","level":"B1","category":"vocab","course":"sales","unit":"sales-2-3","goals":["career"],"title":{"en":"Quotes and terms","tr":"Teklifler ve koşullar","fa":"پیشنهاد قیمت و شرایط"},"cards":[{"word":"quote","sentence":"We sent the quote the same afternoon.","meaning":{"en":"A written price offer with its terms.","tr":"fiyat teklifi.","fa":"پیشنهاد قیمت"}},{"word":"unit price","sentence":"The unit price falls as the quantity rises.","meaning":{"en":"The price of one item.","tr":"birim fiyat.","fa":"قیمت واحد"}},{"word":"minimum order","sentence":"The minimum order is one pallet.","meaning":{"en":"The smallest amount a supplier will sell.","tr":"minimum sipariş miktarı.","fa":"حداقل سفارش"}},{"word":"proforma invoice","sentence":"Their bank needs a proforma invoice before it can open the L/C.","meaning":{"en":"A first invoice sent before the goods, often used for payment or import papers.","tr":"proforma fatura","fa":"پیش‌فاکتور"}},{"word":"deposit","sentence":"We need a 30% deposit before production.","meaning":{"en":"Part of the price paid before the work starts.","tr":"ön ödeme, kapora.","fa":"پیش‌پرداخت"}},{"word":"bill of lading","sentence":"The bill of lading shows that the goods are on the ship.","meaning":{"en":"The shipping document for goods sent by sea.","tr":"konşimento.","fa":"بارنامه"}},{"word":"lead time","sentence":"Our lead time is four weeks in the busy season.","meaning":{"en":"The time between the order and the goods being ready.","tr":"teslim süresi.","fa":"زمان تحویل؛ فاصله‌ی سفارش تا آماده شدن کالا"}},{"word":"valid","sentence":"Is this price still valid?","meaning":{"en":"Usable; still true for a time.","tr":"geçerli.","fa":"معتبر"}},{"word":"freight forwarder","sentence":"Our freight forwarder booked space on the next ship.","meaning":{"en":"A company that arranges transport for goods.","tr":"nakliye organizatörü, forwarder.","fa":"شرکت حمل‌ونقل و ترخیص (فورواردر)"}},{"word":"payment terms","sentence":"Our payment terms are on page two.","meaning":{"en":"When and how the buyer pays.","tr":"ödeme koşulları.","fa":"شرایط پرداخت"}}]},"judge":{"id":"c-sales-2-3-j","course":"sales","unit":"sales-2-3","type":"judge","title":{"en":"Is the quote complete?","tr":"Teklif eksiksiz mi?","fa":"پیشنهاد کامل است؟"},"prompt":"Four quotes for 100 cartons of roasted almonds.","parts":["Price clear","Terms clear","Dates clear"],"instruction":{"en":"Tap what each quote has. The one to send has all three.","tr":"Her teklifte ne olduğuna dokun. Gönderilecek olanda üçü de var.","fa":"روی چیزهایی که هر پیشنهاد دارد بزن. پیشنهادی که باید بفرستی هر سه را دارد."},"items":[{"by":"New rep","answer":"The almonds are about 40 euros, and we can deliver quickly. Please tell me if that's OK.","present":[],"fix":{"en":"'About', 'quickly' and no terms. Give the exact unit price, the Incoterm, the payment and a lead time.","tr":"'About', 'quickly' ve koşul yok. Tam birim fiyatı, Incoterm'i, ödemeyi ve teslim süresini yaz.","fa":"«About» و «quickly»، و هیچ شرطی هم در آن نیست. قیمت واحد دقیق، اینکوترم، پرداخت و زمان تحویل را بنویس."}},{"by":"AI tool","answer":"We are delighted to offer a highly competitive price of EUR 42.00 per carton for your esteemed company.","present":["Price clear"],"fix":{"en":"A price in a lot of air. Cut the praise and add terms and dates.","tr":"Bol laf içinde bir fiyat. Övgüleri çıkar, koşulları ve tarihleri ekle.","fa":"فقط یک قیمت است در میان کلی حرف. تعریف‌ها را حذف کن و شرایط و تاریخ را اضافه کن."}},{"by":"Sales rep","answer":"EUR 42.00 per 5 kg carton, FCA Izmir, Incoterms 2020. Payment: 30% in advance, 70% before shipment.","present":["Price clear","Terms clear"],"fix":{"en":"Good, but when can it ship, and how long does the price hold? Add the lead time and the validity.","tr":"İyi ama ne zaman yola çıkar, fiyat ne kadar geçerli? Teslim süresini ve geçerliliği ekle.","fa":"خوب است، ولی کی ارسال می‌شود و قیمت تا کی معتبر است؟ زمان تحویل و اعتبار را اضافه کن."}},{"by":"Good model","answer":"EUR 42.00 per 5 kg carton, FCA Izmir, Incoterms 2020. Payment: 30% in advance, 70% before shipment. Lead time: four weeks after the deposit. Valid for 30 days.","present":["Price clear","Terms clear","Dates clear"],"fix":null}]},"speaking":{"id":"sales-2-3","course":"sales","unit":"sales-2-3","topic":{"en":"Explaining the quote by phone","tr":"Teklifi telefonda açıklamak","fa":"توضیح پیشنهاد قیمت پشت تلفن"},"warmup":{"en":"Which part of a quote do buyers ask about most in your work?","tr":"Senin işinde alıcılar teklifin en çok hangi kısmını soruyor?","fa":"در کار تو خریدارها بیشتر از همه درباره‌ی کدام بخش پیشنهاد می‌پرسند؟"},"questions":[{"en":"Read a quote aloud clearly: product, quantity, price, Incoterm, payment, lead time, validity. Yours, or: 100 cartons of roasted almonds, EUR 42.00 each, FCA Izmir, 30% in advance, four weeks after the deposit, valid 30 days.","tr":"Bir teklifi net biçimde yüksek sesle oku: ürün, miktar, fiyat, Incoterm, ödeme, teslim süresi, geçerlilik. Kendi teklifin ya da şu: 100 koli kavrulmuş badem, kolisi 42,00 euro, FCA İzmir, %30 peşin, ön ödemeden dört hafta sonra, 30 gün geçerli.","fa":"یک پیشنهاد را روشن و بلند بخوان: محصول، مقدار، قیمت، اینکوترم، پرداخت، زمان تحویل، اعتبار. پیشنهاد خودت یا این: ۱۰۰ کارتن بادام برشته، هر کارتن ۴۲ یورو، FCA ازمیر، ۳۰ درصد پیش‌پرداخت، چهار هفته بعد از پیش‌پرداخت، اعتبار ۳۰ روز."},{"en":"The buyer asks: 'And if we order twice as much?' Answer with if.","tr":"Alıcı soruyor: 'And if we order twice as much?' If ile cevap ver.","fa":"خریدار می‌پرسد: «And if we order twice as much?» با if جواب بده."},{"en":"The buyer asks: 'Can you start now and take the deposit later?' Say no politely with unless.","tr":"Alıcı soruyor: 'Can you start now and take the deposit later?' Unless ile kibarca hayır de.","fa":"خریدار می‌پرسد: «Can you start now and take the deposit later?» با unless مؤدبانه نه بگو."}],"followups":[{"en":"Say your own product's quote from memory. Which of the seven answers do you still need to find out?","tr":"Kendi ürününün teklifini ezberden söyle. Yedi cevaptan hangilerini hâlâ öğrenmen gerekiyor?","fa":"پیشنهاد محصول خودت را از حفظ بگو. کدام یک از هفت جواب را هنوز باید پیدا کنی؟"}],"expressions":[{"phrase":"The unit price is ... for ... or more","meaning":{"en":"Gives a price with a quantity.","tr":"Fiyatı miktarla birlikte söyler.","fa":"قیمت را با مقدار می‌گوید."}},{"phrase":"Lead time is ... after ...","meaning":{"en":"Counts from a clear event.","tr":"Net bir olaydan itibaren sayar.","fa":"از یک رویداد مشخص می‌شمارد."}},{"phrase":"We can't ... unless ...","meaning":{"en":"States a firm condition.","tr":"Kesin bir koşul koyar.","fa":"شرطی قطعی را می‌گوید."}}],"model":"Let me go through the quote. The unit price is forty-two euros per carton for one hundred or more, FCA Izmir, Incoterms 2020. If you order two hundred, the price will be forty euros. Payment is thirty percent in advance. We can't start unless the deposit arrives. Lead time is four weeks after that, and the quote is valid for thirty days.","selfCheck":[{"en":"I gave all seven answers.","tr":"Yedi cevabın hepsini verdim.","fa":"هر هفت جواب را دادم."},{"en":"I said numbers slowly and clearly.","tr":"Rakamları yavaş ve net söyledim.","fa":"عددها را آرام و روشن گفتم."},{"en":"I used no will after if, and a positive verb after unless.","tr":"If'ten sonra will kullanmadım, unless'tan sonra olumlu fiil kullandım.","fa":"بعد از if، will نیاوردم و بعد از unless فعل مثبت گفتم."},{"en":"I said no without sounding rude.","tr":"Kaba görünmeden hayır dedim.","fa":"بدون بی‌ادبی نه گفتم."}]},"writing":{"id":"c-sales-2-3-w","course":"sales","unit":"sales-2-3","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Your terms sheet and quote","tr":"Koşul sayfan ve teklifin","fa":"برگه‌ی شرایط و پیشنهاد قیمت تو"},"portfolio":"sales-final-3","prompt":{"en":"Write a quote email (80-110 words) for your own product, or: roasted almonds in 5 kg cartons; EUR 42.00 each for 100 or more, EUR 40.00 for 200 or more; FCA Izmir; 30% in advance, 70% before shipment; four weeks after the deposit; valid 30 days. Include one line with if and one line with unless.","tr":"Kendi ürünün için ya da şunun için teklif e-postası yaz (80-110 kelime): 5 kg kolide kavrulmuş badem; 100 ve üzeri için adedi 42,00 euro, 200 ve üzeri için 40,00 euro; FCA İzmir; %30 peşin, %70 sevkiyattan önce; ön ödemeden dört hafta sonra; 30 gün geçerli. Bir satırda if, bir satırda unless kullan.","fa":"برای محصول خودت، یا این محصول، ایمیل پیشنهاد قیمت بنویس (۸۰ تا ۱۱۰ کلمه): بادام برشته در کارتن ۵ کیلویی؛ برای ۱۰۰ کارتن یا بیشتر هر کدام ۴۲ یورو، برای ۲۰۰ یا بیشتر ۴۰ یورو؛ FCA ازمیر؛ ۳۰ درصد پیش‌پرداخت، ۷۰ درصد قبل از ارسال؛ چهار هفته بعد از پیش‌پرداخت؛ اعتبار ۳۰ روز. در یک خط if و در یک خط unless به کار ببر."},"model":"Dear Ms Dubois,\n\nThank you for your enquiry about roasted almonds. Here is our quote.\n\nProduct: roasted almonds, 5 kg cartons.\nPrice: EUR 42.00 per carton for 100 or more. If you order 200 or more, the price will be EUR 40.00.\nDelivery: FCA Izmir, Incoterms 2020.\nPayment: 30% in advance, 70% before shipment.\nLead time: four weeks after the deposit. We can't start unless the deposit arrives.\nValidity: 30 days.\n\nCould we speak on Thursday to go through any questions?\n\nBest regards","frame":"Dear ___,\n\nThank you for ___. Here is our quote.\n\nProduct: ___.\nPrice: ___. If you order ___, the price will be ___.\nDelivery: ___, Incoterms 2020.\nPayment: ___.\nLead time: ___. We can't start unless ___.\nValidity: ___.\n\nCould we ___?\n\nBest regards","words":[{"word":"If you order"},{"word":"unless"},{"word":"Incoterms 2020"}],"minWords":70,"minSentences":5,"rubric":["Task done: product, price, Incoterm, payment, lead time, validity, next step","Organised: one short line for each term","Language: if + present, unless + positive verb","Tone: exact and honest; every number can be checked"],"rubricI18n":{"tr":["Görev: ürün, fiyat, Incoterm, ödeme, teslim süresi, geçerlilik, sonraki adım","Düzen: her koşul için kısa bir satır","Dil: if + geniş zaman, unless + olumlu fiil","Üslup: net ve dürüst; her rakam kontrol edilebilir"],"fa":["کامل بودن کار: محصول، قیمت، اینکوترم، پرداخت، زمان تحویل، اعتبار، قدم بعدی","نظم: برای هر شرط یک خط کوتاه","زبان: زمان حال بعد از if و فعل مثبت بعد از unless","لحن: دقیق و صادق؛ هر عدد قابل‌بررسی است"]},"parts":[{"t":{"en":"Product, quantity and unit price","tr":"Ürün, miktar ve birim fiyat","fa":"محصول، مقدار و قیمت واحد"},"find":["eur","usd","per carton","per kilo","a kilo","each","price:"],"sample":"roasted almonds, 5 kg cartons · EUR 42.00 each for 100 or more"},{"t":{"en":"Incoterm and payment","tr":"Incoterm ve ödeme","fa":"اینکوترم و پرداخت"},"find":["fca","fob","cfr","cif","cip","exw","dap","incoterms 2020","in advance","payment:"],"sample":"FCA Izmir, Incoterms 2020 · 30% in advance, 70% before shipment"},{"t":{"en":"Lead time from a clear event","tr":"Net bir olaydan itibaren teslim süresi","fa":"زمان تحویل، از یک اتفاق مشخص"},"find":["after the deposit","lead time","weeks after","days after"],"sample":"four weeks after the deposit"},{"t":{"en":"How long the price holds","tr":"Fiyatın ne kadar geçerli olduğu","fa":"قیمت تا کی معتبر است"},"find":["valid","validity"],"sample":"30 days"},{"t":{"en":"Your conditions: if ..., unless ...","tr":"Koşulların: if ..., unless ...","fa":"شرط‌هایت: ⁨if ...⁩ و ⁨unless ...⁩"},"find":["if you","unless"],"sample":"200+ cartons: EUR 40.00 · no start until the deposit arrives"}]},"exit":{"id":"c-sales-2-3-x","course":"sales","unit":"sales-2-3","type":"exit","items":[{"from":"sales-2-3","kind":"blank","prompt":"We can't book the ship unless the buyer ___ the order.","options":["doesn't confirm","will confirm","confirms"],"correct":2,"point":2,"why":{"en":"confirms: after 'unless', use the present for the future, with no 'not'. 'Doesn't confirm' makes a double negative; 'will confirm' is wrong after unless.","tr":"confirms: 'unless'ten sonra gelecek için geniş zaman gelir, olumsuzluk eklenmez. 'Doesn't confirm' çift olumsuz olur; 'will confirm' unless'ten sonra yanlıştır.","fa":"confirms درست است، چون بعد از unless برای آینده زمان حال می‌آید و منفی نمی‌شود. doesn't confirm منفیِ دوتایی می‌سازد و will confirm بعد از unless غلط است."}},{"from":"sales-2-3","kind":"mcq","prompt":"Which line gives a clear lead time?","options":["We ship as soon as we possibly can.","Six weeks after the deposit arrives.","Usually about a month, if all goes well."],"correct":1,"point":1,"why":{"en":"'Six weeks after the deposit arrives' gives a number and a start point. 'As soon as we can' and 'about a month, if all goes well' promise nothing.","tr":"'Six weeks after the deposit arrives' bir sayı ve başlangıç noktası verir. 'As soon as we can' ve 'about a month, if all goes well' hiçbir şey vaat etmez.","fa":"«Six weeks after the deposit arrives» عدد و نقطه‌ی شروع دارد. «as soon as we can» و «about a month, if all goes well» قولی نمی‌دهند."},"hint2":{"en":"A clear lead time counts from an event the buyer can see, such as a payment. Which line does that?","tr":"Net bir teslim süresi, alıcının görebileceği bir olaydan, örneğin bir ödemeden itibaren sayılır. Hangi satır bunu yapıyor?","fa":"زمان تحویلِ روشن از اتفاقی شمرده می‌شود که خریدار آن را می‌بیند، مثلاً یک پرداخت. کدام خط این کار را می‌کند؟"}},{"from":"sales-2-3","kind":"mcq","prompt":"Why does a quote need a validity date?","options":["So an old price can't come back later","So the quote looks longer and more serious","So the buyer pays faster than usual"],"correct":0,"point":1,"why":{"en":"So an old price can't come back later: costs change. A validity date doesn't make a quote look serious or make anyone pay faster.","tr":"Eski bir fiyat sonradan geri gelmesin diye: maliyetler değişir. Geçerlilik tarihi teklifi ciddi göstermek ya da ödemeyi hızlandırmak için değildir.","fa":"تا قیمت قدیمی بعداً برنگردد، چون هزینه‌ها عوض می‌شوند. تاریخ اعتبار برای جدی‌تر نشان دادن پیشنهاد یا سریع‌تر پرداختن نیست."},"hint2":{"en":"Prices change. Without an end date, which price could the buyer hold you to months later?","tr":"Fiyatlar değişir. Bitiş tarihi olmazsa, alıcı aylar sonra seni hangi fiyata bağlı tutabilir?","fa":"قیمت‌ها عوض می‌شوند. اگر تاریخ پایان نباشد، خریدار چند ماه بعد می‌تواند کدام قیمت را از تو بخواهد؟"}},{"from":"sales-2-2","kind":"blank","prompt":"Sea freight is ___ cheaper than air freight for heavy goods.","options":["very","much","more"],"correct":1,"point":2,"why":{"en":"much: it makes a comparative stronger: much cheaper. 'Very cheaper' and 'more cheaper' are wrong.","tr":"much: karşılaştırmayı güçlendirir: much cheaper. 'Very cheaper' ve 'more cheaper' yanlıştır.","fa":"much درست است، چون صفت تفضیلی را قوی‌تر می‌کند: much cheaper. very cheaper و more cheaper غلط‌اند."},"hint2":{"en":"Neither very nor more can go before a word that already has -er. Which word makes the difference bigger?","tr":"Ne very ne de more, zaten -er almış bir kelimenin önüne gelebilir. Hangi kelime farkı büyütür?","fa":"نه ⁨very⁩ و نه ⁨more⁩ قبل از کلمه‌ای که خودش ⁨er⁩ دارد نمی‌آیند. کدام کلمه فرق را بزرگ‌تر نشان می‌دهد؟"}},{"from":"sales-2-1","kind":"mcq","prompt":"A visitor says \"Send me something.\" What is the best reply?","options":["OK, thanks for coming. Goodbye and good luck.","Here are ten catalogues and all our price lists.","I'll send the price sheet tomorrow. Who else should see it?"],"correct":2,"point":1,"why":{"en":"It promises one thing and a time, then finds who else decides. Ten catalogues bury the buyer, and 'goodbye' loses the lead.","tr":"Bir şey ve bir zaman vaat eder, sonra başka kimin karar verdiğini bulur. On katalog alıcıyı boğar; 'goodbye' ise fırsatı kaybettirir.","fa":"یک چیز و یک زمان مشخص قول می‌دهد و بعد می‌پرسد چه کس دیگری تصمیم می‌گیرد. ده کاتالوگ خریدار را غرق می‌کند و «goodbye» فرصت را از دست می‌دهد."},"hint2":{"en":"'Send me something' is a chance. A good reply promises one exact thing with a day, and keeps the talk going.","tr":"'Bana bir şey gönderin' bir fırsattır. İyi bir cevap, günü belli tek bir şey vaat eder ve konuşmayı sürdürür.","fa":"«یک چیزی برایم بفرست» یک فرصت است. جواب خوب یک چیز مشخص را با روزش قول می‌دهد و گفت‌وگو را ادامه می‌دهد."}},{"from":"sales-1-1","kind":"mcq","prompt":"Which sentence is a benefit, not only a feature?","options":["The tin holds 5 litres and has a strong handle on top.","The tin holds 5 litres, so your kitchen refills less often.","The tin is green and white, and it has our logo on it."],"correct":1,"point":2,"why":{"en":"'So your kitchen refills less often' turns the feature into what the buyer gets. The other two only describe the tin.","tr":"'So your kitchen refills less often' özelliği alıcının kazancına çevirir. Diğer ikisi yalnızca tenekeyi anlatır.","fa":"«so your kitchen refills less often» ویژگی را به چیزی که خریدار به دست می‌آورد تبدیل می‌کند. دو گزینه‌ی دیگر فقط قوطی را توصیف می‌کنند."}}]},"explain":{"id":"c-sales-2-3-e","course":"sales","unit":"sales-2-3","type":"explain","level":"B1","title":{"en":"A quote that leaves no questions","tr":"Soru bırakmayan bir teklif","fa":"پیشنهاد قیمتی که سؤالی باقی نمی‌گذارد"},"objective":{"en":"After this lesson, you can write and explain a complete quote: product, price, Incoterm, payment, lead time and validity.","tr":"Bu dersin sonunda ürün, fiyat, Incoterm, ödeme, teslim süresi ve geçerliliği içeren eksiksiz bir fiyat teklifini yazıp açıklayabileceksin.","fa":"بعد از این درس می‌توانی یک پیشنهاد قیمت کامل بنویسی و توضیح بدهی: محصول، قیمت، اینکوترم، پرداخت، زمان تحویل و مدت اعتبار."},"hook":{"en":"A complete quote answers every question the buyer would otherwise have to ask. One missing term brings a question, a delay or a dispute later.","tr":"Eksiksiz bir teklif, alıcının sonradan sormak zorunda kalacağı her soruyu cevaplar. Eksik tek bir koşul sonradan soru, gecikme ya da anlaşmazlık getirir.","fa":"پیشنهاد قیمت کامل به هر سؤالی که خریدار ممکن است داشته باشد جواب می‌دهد. یک شرط جاافتاده بعداً سؤال، تأخیر یا اختلاف می‌آورد."},"before":{"en":"Write a short price quote for one of your products.","tr":"Ürünlerinden biri için kısa bir fiyat teklifi yaz.","fa":"برای یکی از محصولاتت یک پیشنهاد قیمت کوتاه بنویس."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The sales skill","tr":"Satış becerisi","fa":"مهارت فروش"},"head":{"en":"Answer seven questions","tr":"Yedi soruyu cevapla","fa":"به هفت سؤال جواب بده"},"steps":[{"en":"Start with the buyer's need, in one line, so they see the quote fits them.","tr":"Alıcının ihtiyacıyla tek satırda başla; teklifin ona uygun olduğunu görsün.","fa":"با نیاز خریدار در یک خط شروع کن تا ببیند این پیشنهاد مناسب خودش است.","ex":"You asked for 2 pallets a month."},{"en":"What and how much: product, quantity, unit price, currency. Then nobody reads the price wrongly.","tr":"Ne ve ne kadar: ürün, miktar, birim fiyat, para birimi. Böylece kimse fiyatı yanlış anlamaz.","fa":"بگو چه چیزی و چقدر می‌فروشی: محصول، مقدار، قیمت واحد و ارز. این‌طوری کسی قیمت را اشتباه نمی‌فهمد.","ex":"5 kg cartons, 100 cartons, EUR 42.00 each."},{"en":"How it travels and how it is paid: Incoterm, place, payment. These change the real cost.","tr":"Nasıl gider, nasıl ödenir: Incoterm, yer, ödeme. Bunlar gerçek maliyeti değiştirir.","fa":"بگو کالا چطور حمل و پرداخت می‌شود: اینکوترم، محل و شرط پرداخت. این‌ها هزینه‌ی واقعی را تغییر می‌دهند.","ex":"FCA Izmir, Incoterms 2020. 30% in advance."},{"en":"When and until when: lead time from a clear event, and how long the price holds.","tr":"Ne zaman ve ne zamana kadar: net bir olaydan itibaren teslim süresi ve fiyatın geçerlilik süresi.","fa":"بگو کی تحویل می‌دهی و قیمت تا کی اعتبار دارد. زمان تحویل را از یک رویداد مشخص بشمار.","ex":"Four weeks after the deposit. Valid for 30 days."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Terms with if and unless","tr":"if ve unless ile koşullar","fa":"شرط‌ها با if و unless"},"steps":[{"en":"State a condition with if + present, then will or can + verb.","tr":"Bir koşulu if + geniş zaman, sonra will ya da can + fiil ile söyle.","fa":"برای گفتن یک شرط، در بخش if زمان حال بیاور و در بخش دوم will یا can با فعل ساده.","ex":"If you order 200, the price will be EUR 40.00."},{"en":"Use the present after if, not will, even for the future.","tr":"if'ten sonra, gelecek için bile, will değil geniş zaman kullan.","fa":"بعد از if حتی برای آینده زمان حال می‌آید، نه will.","ex":"If you confirm by Friday, not If you will confirm"},{"en":"unless = if not, so the verb after it is positive.","tr":"unless = eğer ... değilse; ardından gelen fiil olumludur.","fa":"کلمه‌ی unless همان «مگر اینکه» است، پس فعل بعدش مثبت است.","ex":"We can't start unless the deposit arrives."}],"table":{"headers":{"en":["Pattern","Example from a quote"],"tr":["Kalıp","Tekliften örnek"],"fa":["الگو","مثال از یک پیشنهاد قیمت"]},"rows":[["If + present, will / can + verb","If you order 200, the price will be EUR 40.00."],["unless + positive verb","We can't start unless the deposit arrives."],["valid + time","This quote is valid for 30 days."],["Incoterm + place","FCA Izmir"]]},"tip":{"en":"Learners write 'if you will order' and 'unless you don't pay', because their own language allows future or a negative there. English uses present after if and a positive verb after unless.","tr":"Türkçede koşulda gelecek zaman olabilir ('sipariş verecekseniz') ve 'unless' anlamı olumsuz bir ekle kurulur ('ödemedikçe'). Bu yüzden 'if you will order' ve 'unless you don't pay' yazılıyor. İngilizcede if'ten sonra geniş zaman, unless'tan sonra olumlu fiil gelir.","fa":"در فارسی بعد از «اگر» فعل التزامی می‌آید («اگر سفارش بدهید»)، ولی گاهی از ترجمه‌ی «خواهید داد» will را هم می‌آوریم. «مگر اینکه» هم با فعل مثبت می‌آید، درست مثل unless: «مگر اینکه پیش‌پرداخت برسد»."},"wrong":"Unless you don't pay by Friday, the price changes.","right":"Unless you pay by Friday, the price changes."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"Quote fast, and keep the numbers honest","tr":"Hızlı teklif ver, rakamları dürüst tut","fa":"سریع پیشنهاد بده و درباره‌ی عددها صادق باش"},"body":{"en":"A fast quote shows you want the order, so try to answer the same day. Check freight and profit first. Put prices in a short table, and attach a proforma invoice if asked.","tr":"Hızlı teklif siparişi istediğini gösterir; aynı gün cevap vermeye çalış. Önce navlunu ve kârını kontrol et. Fiyatları kısa bir tabloya koy, istenirse proforma fatura ekle.","fa":"پیشنهاد سریع نشان می‌دهد سفارش را می‌خواهی؛ پس سعی کن همان روز جواب بدهی. اول کرایه و سودت را بررسی کن. قیمت‌ها را در جدولی کوتاه بگذار و اگر خواستند پیش‌فاکتور هم پیوست کن."},"phrases":[{"phrase":"The unit price is ... for ... or more","meaning":{"en":"Gives a price with a quantity.","tr":"Fiyatı miktarla birlikte söyler.","fa":"قیمت را با مقدار می‌گوید."}},{"phrase":"Lead time is ... after ...","meaning":{"en":"Counts from a clear event.","tr":"Net bir olaydan itibaren sayar.","fa":"از یک رویداد مشخص می‌شمارد."}},{"phrase":"We can't ... unless ...","meaning":{"en":"States a firm condition.","tr":"Kesin bir koşul koyar.","fa":"شرطی قطعی را می‌گوید."}},{"phrase":"quote","meaning":{"en":"A written price offer with its terms.","tr":"fiyat teklifi.","fa":"پیشنهاد قیمت"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"Fill the gaps in a quote","tr":"Teklifin boşluklarını doldur","fa":"جاهای خالی پیشنهاد را پر کن"},"item":"Our price is 42 for the cartons. We can deliver soon. Let us know. Your facts: roasted almonds, 5 kg cartons; EUR 42.00 each for 100 or more; FCA Izmir; 30% in advance, 70% before shipment; four weeks after the deposit; valid 30 days.","answer":"5 kg cartons of roasted almonds: EUR 42.00 each for 100 or more, FCA Izmir, Incoterms 2020. Payment: 30% in advance, 70% before shipment. Lead time: four weeks after the deposit. Valid for 30 days.","walk":[{"en":"42 what? Give the currency, the unit and the minimum quantity.","tr":"42 ne? Para birimini, birimi ve en az miktarı söyle.","fa":"«۴۲» چه چیزی؟ ارز، واحد و حداقل مقدار را بگو."},{"en":"'Soon' means nothing. Count from a clear event, such as the deposit.","tr":"'Soon' bir şey ifade etmez. Ön ödeme gibi net bir olaydan say.","fa":"کلمه‌ی Soon معنایی ندارد؛ از یک رویداد مشخص، مثل پیش‌پرداخت، بشمار."},{"en":"Add validity, so an old price can't come back later.","tr":"Geçerlilik ekle ki eski fiyat sonra geri gelmesin.","fa":"مدت اعتبار را اضافه کن تا قیمت قدیمی بعداً برنگردد."}],"cut":["42 for the cartons","soon","Let us know"],"cutHint":{"en":"Tap what leaves the buyer with a question.","tr":"Alıcının aklında soru bırakan kısımlara dokun.","fa":"روی چیزهایی بزن که برای خریدار سؤال باقی می‌گذارند."}},"quick":{"prompt":"\"Lead time: four weeks\" is better written as \"four weeks ___\".","options":["after the deposit arrives","or so","if all goes well"],"correct":0,"why":{"en":"after the deposit arrives: a lead time needs a clear start, or nobody knows when it ends.","tr":"after the deposit arrives: teslim süresinin net bir başlangıcı olmalı; yoksa kimse ne zaman biteceğini bilemez.","fa":"جواب after the deposit arrives است، چون زمان تحویل باید شروع روشنی داشته باشد؛ وگرنه کسی نمی‌داند کی تمام می‌شود."}},"remember":{"en":"Need, what, how much, how it travels, how it is paid, when, until when. You can now write a quote with no gaps, which a buyer can answer without asking you anything.","tr":"İhtiyaç, ne, ne kadar, nasıl gider, nasıl ödenir, ne zaman, ne zamana kadar. Artık alıcının sana soru sormadan cevaplayabileceği, boşluksuz bir teklif yazabilirsin.","fa":"نیاز خریدار را بگو و بعد روشن کن چه چیزی، چقدر، چطور حمل و پرداخت می‌شود، کی می‌رسد و تا کی اعتبار دارد. حالا می‌توانی پیشنهادی بدون جای خالی بنویسی که خریدار بدون سؤال اضافه بتواند به آن جواب بدهد."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"Firm conditions: provided that, as long as","tr":"Net koşullar: provided that, as long as","fa":"شرط‌های قاطع: provided that و as long as"},"steps":[{"en":"provided (that) / as long as / on condition that = only if.","tr":"provided (that) / as long as / on condition that = yalnızca ... ise.","fa":"عبارت‌های provided (that)، as long as و on condition that یعنی «فقط به شرطی که».","ex":"as long as the order is 200 or more"},{"en":"Present after them, never will.","tr":"Ardından geniş zaman, asla will değil.","fa":"بعد از این عبارت‌ها زمان حال می‌آید، هرگز will.","ex":"Provided you confirm by Friday, ..."},{"en":"Speech: as long as. Emails and contracts: provided that.","tr":"Konuşma: as long as. E-posta ve sözleşme: provided that.","fa":"در گفتار as long as بهتر است و در ایمیل و قرارداد provided that.","ex":"..., provided that the deposit arrives this month."}],"table":{"headers":{"en":["Word","Feel","Example"],"tr":["Kelime","Hissi","Örnek"],"fa":["کلمه","حس","مثال"]},"rows":[["as long as","spoken, friendly","as long as the order is 200 or more"],["provided (that)","written, firm","provided that the deposit arrives this month"],["on condition that","very formal, contracts","on condition that the price is not published"]]},"body":{"en":"B2: write one term in your quote with provided that or as long as.","tr":"B2: teklifindeki bir koşulu provided that ya da as long as ile yaz.","fa":"مسیر B2: یکی از شرط‌های پیشنهادت را با provided that یا as long as بنویس."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
